def ingress(s, o):
    if o is None: return 'InputRejected'
    if s['utterance']['source'] != 'authored_fixture' or o['mode'] != 'synthetic_verified_fixture': return 'untrusted_text'
    if s['utterance']['complete_transport'] is not True: return 'transport_truncated'
    for k in ('call_local_id','turn_id','state_revision','policy_hash','api_hash'):
        if s[k] != o[k]: return 'stale_binding'
    if s['utterance']['source_turn_id'] != o['source_event_id']: return 'stale_binding'
    return None

def reference(s, o, case):
    reason = ingress(s,o)
    if reason: return None, reason
    kind = case['kind']
    if kind == 'readback':
        raw = s['active_readback']
        if not isinstance(raw,dict) or raw.get('valid') is not True or raw.get('completed_speech') is not True: return None,'unresolved_reference'
        rid = raw.get('readback_id')
    else:
        rid = s['question'].get('spoken_offer_id')
        matches = [r for r in s['spoken_offers'] if r.get('offer_id') == rid]
        if len(matches) != 1: return None,'unresolved_reference'
        raw = matches[0]
        if raw.get('superseded') is not False: return None,'unresolved_reference'
    if not isinstance(rid,str) or not rid: return None,'unresolved_reference'
    spoken = raw.get('spoken_turn_id')
    revision = raw.get('state_revision')
    if not isinstance(spoken,str) or not spoken or type(revision) is not int or revision < 0: return None,'unresolved_reference'
    reg = o['registry'].get(rid)
    if not isinstance(reg,dict) or reg.get('completed_speech') is not True or reg.get('superseded') is not False: return None,'unresolved_reference'
    if reg['kind'] != kind or reg['spoken_event_id'] != spoken or reg['created_state_revision'] != revision: return None,'stale_binding'
    if reg['call_local_id'] != o['call_local_id'] or reg['policy_hash'] != o['policy_hash'] or reg['api_hash'] != o['api_hash']: return None,'stale_binding'
    order = o['event_order']
    if spoken not in order or o['source_event_id'] not in order: return None,'unresolved_reference'
    if revision > o['state_revision'] or order[spoken] >= order[o['source_event_id']]: return None,'stale_binding'
    if set(raw.get('target_indices',[])) != set(reg['target_indices']): return None,'unresolved_reference'
    deps = reg['dependency_tokens']
    if kind == 'readback':
        raw_deps = {str(t)+'/'+c:tok for t,cs in raw.get('component_revisions',{}).items() for c,tok in cs.items()}
        if raw_deps != deps: return None,'unresolved_reference'
    current = dict(o['current_component_tokens'])
    current.update(case.get('same_turn_component_updates',{}))
    for key,token in deps.items():
        actual = current.get(key)
        if not isinstance(token,str) or not token or not isinstance(actual,str) or not actual: return None,'unresolved_reference'
        if actual != token: return None,'stale_binding'
    return rid,None

def merge(case):
    rows = {r['row_id']:r for r in case['rows']}
    if len(rows) != len(case['rows']): raise ValueError('duplicate row')
    retired = set()
    for edge in case['explicit_edges']:
        if edge['old'] not in rows or edge['new'] not in rows: raise ValueError('missing correction endpoint')
        retired.add((edge['old'],edge['component']))
    names = set(case['prior_unresolved'])
    names.update(c for r in rows.values() for c in r['facts'])
    names.update(c for r in rows.values() for c in r['explicit_unfinished'])
    result, needs = {},set(case['prior_unresolved'])
    for c in names:
        # Detect a cycle for this component; no arbitrary last-row selection.
        links = [(x['old'],x['new']) for x in case['explicit_edges'] if x['component']==c]
        pending = set(rows)
        while pending:
            roots = {x for x in pending if not any(b==x and a in pending for a,b in links)}
            if not roots: break
            pending -= roots
        if pending:
            needs.add(c);continue
        survivors = [r for rid,r in rows.items() if (rid,c) not in retired]
        unfinished = any(not r['row_complete'] and c in r['explicit_unfinished'] for r in survivors)
        values = {r['facts'][c]['value'] for r in survivors if c in r['facts'] and c not in r['explicit_unfinished']}
        if unfinished: needs.add(c)
        if len(values)==1:
            # A complete sibling may discharge an earlier open component only
            # through the fixture's explicit completion relation.
            open_rows = [r['row_id'] for r in survivors if not r['row_complete'] and c in r['explicit_unfinished']]
            complete_rows = {r['row_id'] for r in survivors if c in r['facts'] and c not in r['explicit_unfinished']}
            resolved = not open_rows or all(any(x['from_row']==rid and x['component']==c and x['to_row'] in complete_rows for x in case.get('completed_links',[])) for rid in open_rows)
            if resolved: result[c]=next(iter(values));needs.discard(c)
        elif len(values)>1: needs.add(c)
    return result,sorted(needs)
